CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, family TEXT NOT NULL, notes TEXT NOT NULL, blurb TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL, price_is_placeholder INTEGER NOT NULL DEFAULT 0, stock INTEGER, is_live INTEGER NOT NULL DEFAULT 1, longevity INTEGER NOT NULL DEFAULT 85, sillage INTEGER NOT NULL DEFAULT 80, image_key TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, ref TEXT UNIQUE NOT NULL, customer_name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT DEFAULT '', province TEXT NOT NULL DEFAULT '', city TEXT NOT NULL, area TEXT DEFAULT '', address TEXT NOT NULL, note TEXT DEFAULT '', items TEXT NOT NULL, subtotal INTEGER NOT NULL, discount INTEGER NOT NULL DEFAULT 0, promo_code TEXT DEFAULT '', delivery_fee INTEGER NOT NULL, total INTEGER NOT NULL, shipping_method TEXT NOT NULL, payment_method TEXT NOT NULL, advance_paid INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL, courier_name TEXT NOT NULL DEFAULT '', courier_tracking TEXT NOT NULL DEFAULT '', courier_status TEXT NOT NULL DEFAULT '', postex_booking_pending INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shipping_methods (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, eta TEXT NOT NULL DEFAULT '', fee INTEGER NOT NULL, free_over INTEGER, is_active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payment_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, label TEXT NOT NULL, account_title TEXT NOT NULL DEFAULT '', account_number TEXT NOT NULL DEFAULT '', bank_name TEXT DEFAULT '', iban TEXT DEFAULT '', instructions TEXT DEFAULT '', is_active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_slug TEXT NOT NULL, display_name TEXT NOT NULL, rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), comment TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (order_id, product_slug));
CREATE TABLE IF NOT EXISTS courier_labels (order_id INTEGER PRIMARY KEY REFERENCES orders(id), tracking TEXT NOT NULL, pdf BLOB NOT NULL);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_orders_phone ON orders(phone);
CREATE INDEX IF NOT EXISTS idx_reviews_product_status ON reviews(product_slug, status);
